// CHANGE-ME: Zammad-Gruppe + Requester ggf. anpassen (siehe docs/f-cicd-automatisierung/f0040-github-release-watcher.md fuer die Regeln dazu -- ZAMMAD_REQUESTER_EMAIL muss ein bereits existierender Zammad-User sein).
const ZAMMAD_GROUP = 'Support::Administration';
const ZAMMAD_REQUESTER_EMAIL = 'info@edv-kretzer.de';

// Wie lange (ms) ein inhaltsgleicher Alarm als Duplikat gilt -- schuetzt
// gegen Mehrfach-Tickets, falls der AMweb-Webhook pro offenem Kiosk-Tab
// feuert (bis zu 3 Standorte moeglich, siehe
// docs/4-planung/40060-alamos-einsatz-email-benachrichtigung.md,
// offene Punkte -- ob das tatsaechlich passiert, war ohne Alamos-Login
// nicht abschliessend zu klaeren).
const DEDUP_WINDOW_MS = 2 * 60 * 1000;

// Beide Webhook-Trigger-Varianten (GET-Query-Parameter ODER POST-JSON-Body)
// zusammenfuehren -- welche Variante ihr in AMweb konfiguriert (AMweb-Seiten-
// Webhook vs. "Allgemeine Webhooks"), war ohne Alamos-Login nicht
// abschliessend zu klaeren, siehe docs/4-planung/40060-....
const raw = $input.item.json;
const merged = { ...(raw.query || {}), ...(raw.body || {}) };

// Bekannte Platzhalter laut Alamos-Handbuch (Allgemeine Webhooks): "keyword"
// und "unit". Weitere Feldnamen (Adresse, Fahrzeuge, Meldebild, ...) sind
// nur in der eingeloggten Webhook-Vorschau/"Webhook Test" des
// Alamos-Accounts einsehbar -- deshalb werden unten ALLE empfangenen Felder
// unveraendert mit ausgegeben, nicht nur eine feste Vorauswahl ("alle Daten
// die moeglich sind abgreifen").
const keyword = merged.keyword || merged.stichwort || merged.Stichwort || null;
const unit = merged.unit || merged.station || null;

// Weder keyword noch unit vorhanden -- kein echter Einsatzalarm, sondern
// z.B. ein Verbindungstest/Health-Check gegen alamos-relay/den Webhook
// (leerer GET-Call ohne Query-Parameter, curl-Test, Alamos-"Webhook Test"
// ohne echte Auswahl). Kein Ticket, aber sichtbar im Execution-Log, damit
// ein echter Alarm mit unerwarteten Feldnamen nicht denselben Weg lautlos
// nimmt und unbemerkt durchrutscht.
if (!keyword && !unit) {
  console.log('Kein keyword/unit im Payload -- vermutlich Test-Call, kein Ticket. Rohdaten:', JSON.stringify(merged));
  return [];
}

const title = keyword
  ? `ALAMOS-Einsatzalarm: ${keyword}${unit ? ` (${unit})` : ''}`
  : `ALAMOS-Einsatzalarm${unit ? ` (${unit})` : ''}`;

const fieldLines = Object.entries(merged)
  .map(([key, value]) => `- ${key}: ${typeof value === 'object' ? JSON.stringify(value) : value}`)
  .join('\n');

const bodyText = [
  'Neuer Einsatzalarm von ALAMOS AMweb.',
  '',
  'Empfangene Rohdaten (alles, was der Webhook mitgeliefert hat):',
  fieldLines,
  '',
  `Empfangen: ${new Date().toISOString()}`,
].join('\n');

// Duplikat-Schutz ueber Workflow-Static-Data (ueberlebt einzelne
// Workflow-Laeufe, aber keinen n8n-Neustart -- fuer den Zweck ausreichend,
// da echte Mehrfach-Ausloesungen desselben Alarms innerhalb von Sekunden
// eintreffen wuerden, nicht erst nach einem Neustart).
const staticData = $getWorkflowStaticData('node');
staticData.recentAlarms = staticData.recentAlarms || {};

const dedupKey = keyword && unit ? `${keyword}|${unit}` : JSON.stringify(merged);
const now = Date.now();

for (const [existingKey, ts] of Object.entries(staticData.recentAlarms)) {
  if (now - ts > DEDUP_WINDOW_MS) delete staticData.recentAlarms[existingKey];
}

if (staticData.recentAlarms[dedupKey] !== undefined) {
  // Duplikat innerhalb des Zeitfensters -- kein zweites Ticket erzeugen.
  return [];
}
staticData.recentAlarms[dedupKey] = now;

return [{
  json: {
    title,
    group: ZAMMAD_GROUP,
    customer: ZAMMAD_REQUESTER_EMAIL,
    body: bodyText,
  },
}];
